using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

// --- Service setup -----------------------------------------------------------

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
var sp = services.BuildServiceProvider();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// Build the MEAI chat client from the OpenAI provider SDK.
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tool definitions --------------------------------------------------------

var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    SearchWebAsync,
    new AIFunctionFactoryOptions { Name = "search_web" });

var addNoteTool = AIFunctionFactory.Create(
    notebook.AddNote,
    new AIFunctionFactoryOptions { Name = "add_note" });

var readNotesTool = AIFunctionFactory.Create(
    notebook.ReadNotes,
    new AIFunctionFactoryOptions { Name = "read_notes" });

// --- Agent -------------------------------------------------------------------

var agentOptions = new ChatClientAgentOptions
{
    Instructions = """
        You are a research assistant. Your goal is to thoroughly research a topic
        the user gives you by searching the web and taking notes on your findings.

        Follow this workflow:
        1. Break the topic into 2-3 specific search queries.
        2. For each query, call search_web to retrieve results.
        3. Call add_note for every important finding (include the source URL).
        4. After all searches, call read_notes to review your collected notes.
        5. Produce a well-structured summary with sections, key facts, and source
           citations. The summary should be informative and concise.
        """,
    DefaultChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [searchTool, addNoteTool, readNotesTool],
        ToolMode = ChatToolMode.Auto,
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory, sp);

Console.WriteLine($"🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
    session,
    new ChatClientAgentRunOptions { MaximumIterations = 15 });

Console.WriteLine(response.Message?.Text ?? "No response received.");
Console.WriteLine($"\n📊 Notes collected: {notebook.Count}");

// --- Tool implementations ----------------------------------------------------

[Description("Search the web for a query and return relevant results with titles, snippets, and URLs.")]
static async Task<string> SearchWebAsync(
    [Description("The search query string")] string query,
    CancellationToken cancellationToken = default)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    // Use Bing search to retrieve real web results.
    var encodedQuery = WebUtility.UrlEncode(query);
    var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var html = await http.GetStringAsync(url, cancellationToken);
        return ParseSearchResults(html, maxResults: 5);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static string ParseSearchResults(string html, int maxResults)
{
    var results = new List<string>();
    var snippetTag = "class=\"result__snippet\"";
    var titleTag = "class=\"result__a\"";
    var urlTag = "class=\"result__url\"";

    var pos = 0;
    while (results.Count < maxResults)
    {
        var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
        if (titleStart < 0) break;

        var title = ExtractTagContent(html, titleStart);
        var snippet = "";
        var link = "";

        var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
        if (snippetStart >= 0)
            snippet = ExtractTagContent(html, snippetStart);

        var urlStart = html.IndexOf(urlTag, titleStart, StringComparison.Ordinal);
        if (urlStart >= 0)
            link = ExtractTagContent(html, urlStart).Trim();

        if (!string.IsNullOrWhiteSpace(title))
            results.Add($"[{results.Count + 1}] {StripHtml(title)}\n    URL: {StripHtml(link)}\n    {StripHtml(snippet)}");

        pos = titleStart + 1;
    }

    return results.Count > 0
        ? string.Join("\n\n", results)
        : "No results found.";
}

static string ExtractTagContent(string html, int tagAttributePos)
{
    var closeTag = html.IndexOf('>', tagAttributePos);
    if (closeTag < 0) return "";
    var endTag = html.IndexOf('<', closeTag + 1);
    if (endTag < 0) return "";
    return html[(closeTag + 1)..endTag];
}

static string StripHtml(string text) =>
    System.Text.RegularExpressions.Regex.Replace(
        WebUtility.HtmlDecode(text), "<[^>]+>", "").Trim();

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// --- Notebook service --------------------------------------------------------

sealed class Notebook
{
    private readonly List<string> _notes = [];
    public int Count => _notes.Count;

    [Description("Save a research note. Use this to record important findings from search results.")]
    public string AddNote(
        [Description("The note content to save, including source URL if available")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Read all saved research notes to review findings before writing the summary.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var result = string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}:\n{n}"));
        Console.WriteLine($"  📖 Reading {_notes.Count} notes");
        return result;
    }
}

