+        if (urlStart >= 0)
+            link = ExtractTagContent(html, urlStart).Trim();
+
+        if (!string.IsNullOrWhiteSpace(title))
+            results.Add($"[{results.Count + 1}] {StripHtml(title)}\n    URL: {StripHtml(link)}\n    {StripHtml(snippet)}");
+
+        pos = titleStart + 1;
+    }
+
+    return results.Count > 0
+        ? string.Join("\n\n", results)
+        : "No results found.";
+}
+
+static string ExtractTagContent(string html, int tagAttributePos)
+{
+    var closeTag = html.IndexOf('>', tagAttributePos);
+    if (closeTag < 0) return "";
+    var endTag = html.IndexOf('<', closeTag + 1);
+    if (endTag < 0) return "";
+    return html[(closeTag + 1)..endTag];
+}
