using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

// --- Service setup -----------------------------------------------------------

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
var sp = services.BuildServiceProvider();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tool definitions --------------------------------------------------------

var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    SearchWebAsync,
    new AIFunctionFactoryOptions { Name = "search_web" });

var addNoteTool = AIFunctionFactory.Create(
    notebook.AddNote,
    new AIFunctionFactoryOptions { Name = "add_note" });

var readNotesTool = AIFunctionFactory.Create(
    notebook.ReadNotes,
    new AIFunctionFactoryOptions { Name = "read_notes" });

// Build the MEAI chat client from the OpenAI provider SDK, wrapped with
// FunctionInvokingChatClient so the agent framework auto-dispatches tool calls.
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation(o => o.MaximumIterationsPerRequest = 15)
    .Build();

// --- Agent -------------------------------------------------------------------

const string instructions = """
    You are a research assistant. Your goal is to thoroughly research a topic
    the user gives you by searching the web and taking notes on your findings.

    Follow this workflow:
    1. Break the topic into 2-3 specific search queries.
    2. For each query, call search_web to retrieve results.
    3. Call add_note for every important finding (include the source URL).
    4. After all searches, call read_notes to review your collected notes.
    5. Produce a well-structured summary with sections, key facts, and source
       citations. The summary should be informative and concise.
    """;

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics via web search and note-taking",
    instructions: instructions,
    tools: [searchTool, addNoteTool, readNotesTool],
    loggerFactory: loggerFactory,
    services: sp);

// Pin temperature and token budget on the agent's chat options.
agent.ChatOptions.Temperature = 0f;
agent.ChatOptions.MaxOutputTokens = 2048;

Console.WriteLine($"🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
    session);

Console.WriteLine(response.Message?.Text ?? "No response received.");
Console.WriteLine($"\n📊 Notes collected: {notebook.Count}");

