1. using System.ComponentModel;
2. using System.Net;
3. using Microsoft.Agents.AI;
4. using Microsoft.Extensions.AI;
5. using Microsoft.Extensions.DependencyInjection;
6. using Microsoft.Extensions.Logging;
7. using OpenAI;
8. 
9. // --- Configuration -----------------------------------------------------------
10. 
11. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
12.     ?? throw new InvalidOperationException(
13.         "Set the OPENAI_API_KEY environment variable before running.");
14. 
15. var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";
16. 
17. var topic = args.Length > 0
18.     ? string.Join(' ', args)
19.     : PromptForTopic();
20. 
21. // --- Service setup -----------------------------------------------------------
22. 
23. var services = new ServiceCollection();
24. services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
25. var sp = services.BuildServiceProvider();
26. var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
27. 
28. // --- Tool definitions --------------------------------------------------------
29. 
30. var notebook = new Notebook();
31. 
32. var searchTool = AIFunctionFactory.Create(
33.     SearchWebAsync,
34.     new AIFunctionFactoryOptions { Name = "search_web" });
35. 
36. var addNoteTool = AIFunctionFactory.Create(
37.     notebook.AddNote,
38.     new AIFunctionFactoryOptions { Name = "add_note" });
39. 
40. var readNotesTool = AIFunctionFactory.Create(
41.     notebook.ReadNotes,
42.     new AIFunctionFactoryOptions { Name = "read_notes" });
43. 
44. // Build the MEAI chat client from the OpenAI provider SDK, wrapped with
45. // FunctionInvokingChatClient so tool calls are auto-dispatched.
46. IChatClient chatClient = new OpenAIClient(apiKey)
47.     .GetChatClient(modelId)
48.     .AsIChatClient()
49.     .AsBuilder()
50.     .UseFunctionInvocation(configure: fic => fic.MaximumIterationsPerRequest = 15)
51.     .Build();
52. 
53. // --- Agent -------------------------------------------------------------------
54. 
55. const string instructions = """
56.     You are a research assistant. Your goal is to thoroughly research a topic
57.     the user gives you by searching the web and taking notes on your findings.
58. 
59.     Follow this workflow:
60.     1. Break the topic into 2-3 specific search queries.
61.     2. For each query, call search_web to retrieve results.
62.     3. Call add_note for every important finding (include the source URL).
63.     4. After all searches, call read_notes to review your collected notes.
64.     5. Produce a well-structured summary with sections, key facts, and source
65.        citations. The summary should be informative and concise.
66.     """;
67. 
68. var agent = new ChatClientAgent(
69.     chatClient,
70.     name: "ResearchAgent",
71.     description: "An agent that researches topics via web search and note-taking",
72.     instructions: instructions,
73.     tools: [searchTool, addNoteTool, readNotesTool],
74.     loggerFactory: loggerFactory,
75.     services: sp);
76. 
77. Console.WriteLine($"🔍 Researching: {topic}\n");
78. 
79. var session = await agent.CreateSessionAsync();
80. var runOptions = new ChatClientAgentRunOptions
81. {
82.     ChatOptions = new ChatOptions
83.     {
84.         Temperature = 0f,
85.         MaxOutputTokens = 2048,
86.     },
87. };
88. var response = await agent.RunAsync(
89.     $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
90.     session,
91.     runOptions);
92. 
93. Console.WriteLine(response.Text ?? "No response received.");
94. Console.WriteLine($"\n📊 Notes collected: {notebook.Count}");
95. 
96. // --- Tool implementations ----------------------------------------------------
97. 
98. [Description("Search the web for a query and return relevant results with titles, snippets, and URLs.")]
99. static async Task<string> SearchWebAsync(
100.     [Description("The search query string")] string query,
101.     CancellationToken cancellationToken = default)
102. {
103.     Console.WriteLine($"  🌐 Searching: \"{query}\"");
104. 
105.     // Use Bing search to retrieve real web results.
106.     var encodedQuery = WebUtility.UrlEncode(query);
107.     var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
108. 
109.     using var http = new HttpClient();
110.     http.DefaultRequestHeaders.UserAgent.ParseAdd(
111.         "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
112. 
113.     try
114.     {
115.         var html = await http.GetStringAsync(url, cancellationToken);
116.         return ParseSearchResults(html, maxResults: 5);
117.     }
118.     catch (Exception ex)
119.     {
120.         return $"Search failed: {ex.Message}";
121.     }
122. }
123. 
124. static string ParseSearchResults(string html, int maxResults)
125. {
126.     var results = new List<string>();
127.     var snippetTag = "class=\"result__snippet\"";
128.     var titleTag = "class=\"result__a\"";
129.     var urlTag = "class=\"result__url\"";
130. 
131.     var pos = 0;
132.     while (results.Count < maxResults)
133.     {
134.         var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
135.         if (titleStart < 0) break;
136. 
137.         var title = ExtractTagContent(html, titleStart);
138.         var snippet = "";
139.         var link = "";
140. 
141.         var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
142.         if (snippetStart >= 0)
143.             snippet = ExtractTagContent(html, snippetStart);
144. 
145.         var urlStart = html.IndexOf(urlTag, titleStart, StringComparison.Ordinal);
146.         if (urlStart >= 0)
147.             link = ExtractTagContent(html, urlStart).Trim();
148. 
149.         if (!string.IsNullOrWhiteSpace(title))
150.             results.Add($"[{results.Count + 1}] {StripHtml(title)}\n    URL: {StripHtml(link)}\n    {StripHtml(snippet)}");
151. 
152.         pos = titleStart + 1;
153.     }
154. 
155.     return results.Count > 0
156.         ? string.Join("\n\n", results)
157.         : "No results found.";
158. }
159. 
160. static string ExtractTagContent(string html, int tagAttributePos)
161. {
162.     var closeTag = html.IndexOf('>', tagAttributePos);
163.     if (closeTag < 0) return "";
164.     var endTag = html.IndexOf('<', closeTag + 1);
165.     if (endTag < 0) return "";
166.     return html[(closeTag + 1)..endTag];
167. }
168. 
169. static string StripHtml(string text) =>
170.     System.Text.RegularExpressions.Regex.Replace(
171.         WebUtility.HtmlDecode(text), "<[^>]+>", "").Trim();
172. 
173. static string PromptForTopic()
174. {
175.     Console.Write("Enter a research topic: ");
176.     var input = Console.ReadLine()?.Trim();
177.     return string.IsNullOrEmpty(input)
178.         ? throw new InvalidOperationException("A research topic is required.")
179.         : input;
180. }
181. 
182. // --- Notebook service --------------------------------------------------------
183. 
184. sealed class Notebook
185. {
186.     private readonly List<string> _notes = [];
187.     public int Count => _notes.Count;
188. 
189.     [Description("Save a research note. Use this to record important findings from search results.")]
190.     public string AddNote(
191.         [Description("The note content to save, including source URL if available")] string note)
192.     {
193.         _notes.Add(note);
194.         Console.WriteLine($"  📝 Note #{_notes.Count} saved");
195.         return $"Note #{_notes.Count} saved successfully.";
196.     }
197. 
198.     [Description("Read all saved research notes to review findings before writing the summary.")]
199.     public string ReadNotes()
200.     {
201.         if (_notes.Count == 0)
202.             return "No notes saved yet.";
203. 
204.         var result = string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}:\n{n}"));
205.         Console.WriteLine($"  📖 Reading {_notes.Count} notes");
206.         return result;
207.     }
208. }
